/**
 * @brief Return the number of shared scratch variables required by an
 * instruction expansion.
 *
 * @param inst IR instruction being analyzed or emitted.
 * @return Number of shared scratch variables required.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Ok then. But look at how cg handles builtin functions and their
// GF requirements and try to match that. Make me sign of on the commit"
// Changes: Count scratch slots for built-ins and inline instructions.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Reserve scratch only for builtin paths that use it.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Ok, implement all, remove things made redundant by this change"
// Changes: Size scratch storage only for instructions that still need it.
static size_t cg_instruction_helper_count(const IrInstruction* inst) {
  switch (inst->type) {
    // Floor uses one scratch slot for truncation and the correction test.
    case IR_INST_FLOOR:
      return inst->result != IR_INVALID_ID;

    // A discarded division still runs and needs a destination.
    case IR_INST_DIV:
    case IR_INST_IDIV:
      return inst->result == IR_INVALID_ID;

    case IR_INST_CALL:
      break;

    default:
      return 0;
  }

  // Built-ins share the same scratch slots as inline instructions.
  switch (inst->operands.call.type) {
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Reserve only the temporaries used by the chosen substring path.
    case IR_FX_STR_SUB:
      if (cg_single_character_substring(inst))
        return 1;

      return inst->result == IR_INVALID_ID ? 2 : 3;

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Count the scratch used by typed builtin expansions.
    case IR_FX_ORD:
      return inst->result != IR_INVALID_ID;

    case IR_FX_READ_LINE:
    case IR_FX_READ_INT:
    case IR_FX_READ_BOOL:
    case IR_FX_READ_DOUBLE:
    case IR_FX_CHR:
      return inst->result == IR_INVALID_ID;

    default:
      return 0;
  }
}

